//! Fixed programs for the bootstrap channel. Paths are checked positional arguments, never shell source.

pub const PROBE: &str = r#"set -eu; field() { printf "%s=" "$1"; printf "%s" "$2" | od -An -v -tx1 | tr -d " \n" | sed "s/../%&/g"; printf "\n"; }; field uname "$(uname -s) $(uname -m)"; field home "$HOME"; data="${XDG_DATA_HOME:-$HOME/.local/share}/eitri-server"; field data_dir "$data"; field state_dir "${XDG_STATE_HOME:-$HOME/.local/state}/eitri-server"; space="$data"; while ! test -d "$space"; do space=$(dirname "$space"); done; blocks=$(stat -f -c %a "$space"); size=$(stat -f -c %S "$space"); field free_bytes "$((blocks * size))"; field login_shell "${SHELL:-/bin/sh}"; field login_path "$PATH"; if command -v claude >/dev/null 2>&1; then field claude "$(command -v claude)"; fi; if command -v git >/dev/null 2>&1; then field git "$(command -v git)"; fi; glibc=$(getconf GNU_LIBC_VERSION 2>/dev/null || true); case "$glibc" in "glibc "*) field glibc "${glibc#glibc }";; esac; if command -v gzip >/dev/null 2>&1; then field gzip true; else field gzip false; fi; linger=$(loginctl show-user "$(id -u)" -p Linger --value 2>/dev/null || true); case "$linger" in yes) field linger true;; no) field linger false;; esac; kill=$(systemd-analyze cat-config systemd/logind.conf 2>/dev/null | sed -n "s/^[[:space:]]*KillUserProcesses[[:space:]]*=[[:space:]]*//p" | tail -n 1 || true); case "$kill" in yes) field kill_user_processes true;; no) field kill_user_processes false;; esac; field root missing"#;

pub const UPLOAD: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; mkdir -p "$d/bin"; t=$(mktemp "$d/bin/.eitri-server.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; gzip -dc > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/bin/eitri-server""#;

pub const UPLOAD_PLAIN: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; mkdir -p "$d/bin"; t=$(mktemp "$d/bin/.eitri-server.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/bin/eitri-server""#;

pub const UPLOAD_SIDECAR: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; IFS= read -r rev; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; d="$d/sidecar/$rev"; mkdir -p "$d"; t=$(mktemp "$d/.sidecar.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; gzip -dc > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/verdandi-claude-sidecar""#;

pub const UPLOAD_SIDECAR_PLAIN: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; IFS= read -r rev; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; d="$1/$2"; mkdir -p "$d"; exec 8<"$d"; flock -s 8; d="$d/sidecar/$rev"; mkdir -p "$d"; t=$(mktemp "$d/.sidecar.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; chmod 700 "$t"; sync "$t"; mv -f "$t" "$d/verdandi-claude-sidecar""#;

pub const WRITE_MANIFEST: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; d="$1/$2"; exec 8<"$d"; flock -s 8; t=$(mktemp "$d/.manifest.XXXXXX"); trap "rm -f -- \"\$t\"" EXIT HUP INT TERM; cat > "$t"; sync "$t"; mv -f "$t" "$d/MANIFEST""#;

pub const PUBLISH: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; umask 077; IFS= read -r version; IFS= read -r rev; case "$version" in ""|.|..|*[!A-Za-z0-9._+-]*) exit 64;; esac; case "$rev" in ""|.|..|*[!a-f0-9-]*) exit 64;; esac; s="$1/$2"; exec 8<"$s"; flock -s 8; d="$1/$version"; exec 9>"$1/.install.lock"; flock -x 9; find "$1" -mindepth 1 -maxdepth 1 -type d -name ".install-*" ! -path "$s" -mmin +1439 -exec flock -n -x {} rm -rf -- {} \;; cd "$s"; sha256sum --strict --quiet -c MANIFEST; if test -e "$d/MANIFEST"; then cmp -s "$s/MANIFEST" "$d/MANIFEST" || { echo "installation identity already contains different hashes" >&2; exit 65; }; fi; mkdir -p "$d/bin" "$d/sidecar/$rev"; mv -f "$s/bin/eitri-server" "$d/bin/eitri-server"; mv -f "$s/sidecar/$rev/verdandi-claude-sidecar" "$d/sidecar/$rev/verdandi-claude-sidecar"; mv -f "$s/MANIFEST" "$d/MANIFEST"; sync "$d"; rm -rf -- "$s""#;

pub const CLEANUP: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; case "$2" in .install-*) rm -rf -- "$1/$2";; *) exit 64;; esac"#;

pub const START: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; d="$1/$2"; test -d "$d" || exit 66; exec 9>"$1/.install.lock"; flock -s -w 15 9; cd "$d" || exit 66; sha256sum --strict --quiet -c - || exit 67; if test -n "${3:-}"; then l="$3/run/$4/live.lock"; if test -e "$l"; then flock -n -s "$l" true || { echo "an Eitri server daemon still runs" >&2; exit 75; }; fi; fi; (exec ./bin/eitri-server ensure) 9>&-"#;

pub const STOP: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; exec 9>"$1/.install.lock"; flock -s 9; cd "$1/$2"; sha256sum --strict --quiet -c -; (exec ./bin/eitri-server stop-daemon --args-hex "$3") 9>&-"#;

pub const CHECK_SIDECARS: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; test -d "$1/$2" || exit 66; records=false; for p in "$3"/run/*/sc-*.pid; do test ! -e "$p" || records=true; done; "$records" || { cat >/dev/null; exit 0; }; exec 9>"$1/.install.lock"; flock -s 9; cd "$1/$2"; sha256sum --strict --quiet -c - || exit 67; (exec ./bin/eitri-server check-sidecars "$3" --live-runs) 9>&-"#;

pub const UNINSTALL: &str = r#"set -eu; printf "eitri-lifecycle-attached-v1\n"; case "$1" in */eitri-server) ;; *) exit 64;; esac; case "$2" in */eitri-server) ;; *) exit 64;; esac; checkers=$(cat); if test -d "$1"; then exec 9>"$1/.install.lock"; flock -x 9; fi; for l in "$2"/run/*/live.lock; do test -e "$l" || continue; flock -n -s "$l" true || { echo "an Eitri server daemon still runs: $l is held" >&2; exit 75; }; done; records=false; for p in "$2"/run/*/sc-*.pid; do test ! -e "$p" || records=true; done; if "$records"; then printf "%s\n" "$checkers" | (checker=false; clear=false; while read -r installation hash; do if "$clear"; then continue; fi; case "$installation" in ""|.|..|*[!A-Za-z0-9._+-]*) continue;; esac; test -x "$1/$installation/bin/eitri-server" || continue; if (cd "$1/$installation" && printf "%s  bin/eitri-server\n" "$hash" | sha256sum --strict --quiet -c -); then checker=true; if (cd "$1/$installation" && exec ./bin/eitri-server check-sidecars "$2") 9>&-; then clear=true; fi; fi; done; if ! "$clear"; then if "$checker"; then echo "recorded sidecars may still run; their records and helper were not removed" >&2; else echo "no checked sidecar checker installed; their records and helper were not removed" >&2; fi; exit 76; fi); fi; for r in "$2"/run/*; do test -d "$r" || continue; k=${r##*/}; case "$k" in ""|.|..|*[!A-Za-z0-9._+-]*) continue;; esac; rm -rf -- "${TMPDIR:-/tmp}/eitri-server-$(id -u)/$k"; done; rm -rf -- "$2" "$1""#;
